package com.hbm.machine.oilextraction;
import net.minecraft.ChatFormatting;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.chat.Component;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.entity.player.Player;import net.neoforged.bus.api.IEventBus;import net.neoforged.neoforge.network.PacketDistributor;import net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent;
/** Reuses original common PlayerInform inbox/key8; no new actionbar overlay or lifetime. */
public record OilDetectorNotice(int result)implements CustomPacketPayload {
 public static final Type<OilDetectorNotice> TYPE=new Type<>(ResourceLocation.parse("hbm:oil_detector_notice"));public static final StreamCodec<RegistryFriendlyByteBuf,OilDetectorNotice> CODEC=StreamCodec.of((b,p)->b.writeVarInt(p.result),b->new OilDetectorNotice(b.readVarInt()));@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}
 public static void register(IEventBus bus){bus.addListener((RegisterPayloadHandlersEvent event)->event.registrar("1").playToClient(TYPE,CODEC,(p,c)->c.enqueueWork(()->{if(p.result<0||p.result>2)return;String key=new String[]{"bullseye","detected","noOil"}[p.result];var color=new ChatFormatting[]{ChatFormatting.DARK_GREEN,ChatFormatting.GOLD,ChatFormatting.RED}[p.result];com.hbm.item.settings.client.LegacyInfoSystem.push(Component.translatable("item.oil_detector."+key).withStyle(color),8);})) );}
 public static void send(Player player,int result){if(player instanceof ServerPlayer server)PacketDistributor.sendToPlayer(server,new OilDetectorNotice(result));}
}
